import React from "react";

const Message = ({ text, isUser }) => {
  return (
    <div style={{
      textAlign: isUser ? "right" : "left",
      background: isUser ? "#007bff" : "#f1f1f1",
      color: isUser ? "white" : "black",
      padding: "10px",
      borderRadius: "10px",
      margin: "10px",
      display: "inline-block",
    }}>
      {text}
    </div>
  );
};

export default Message;
